owned_rules:
table ip dns_policy_poc {
	set pods {
		type ifname . ipv4_addr
		elements = { "eni3b790ef6f68" . 10.244.0.6 }
	}

	set nat_resolvers {
		type ipv4_addr
		elements = { 10.96.18.73 }
	}

	chain pre {
		type nat hook prerouting priority dstnat - 10; policy accept;
		iifname . ip saddr @pods ip daddr @nat_resolvers meta l4proto { tcp, udp } th dport 53 dnat to 169.254.29.53:50052
	}

	chain rawpre {
		type filter hook prerouting priority raw - 10; policy accept;
		iifname . ip saddr @pods ip daddr != @nat_resolvers meta l4proto { tcp, udp } th dport 53 notrack
	}

	chain rawout {
		type filter hook output priority raw - 10; policy accept;
		oifname . ip daddr @pods meta l4proto { tcp, udp } th sport 53 notrack
	}

	chain transparent {
		type filter hook prerouting priority mangle; policy accept;
		iifname . ip saddr @pods ip daddr != @nat_resolvers meta l4proto { tcp, udp } th dport 53 tproxy to :50052 meta mark set meta mark | 0x20000000 accept
	}
}
